  Lemma seg_H : ltac2:(zQ "ia2!j7!q0!ip8!ik2!h8!jj6!ihf!mve!ir7!iqb!nna!ku6!iva!hif!lre!jmf!jk9!ir1!iq0!q5!llc!nrf!nv6!nvf!oid!oj6!qqc!qrb!qs3!oq6!or2!ora!ovc!pk8!qsb!pl4!qt5!ple!qta!pu8!pv3!lm3&@1$7@2$2@1$1@1$0#8?4path&@2$f@2$h0@1$0#k0?3sp0+ijd>4vals@1$4@1$1@1$0#k0>1R@2$h8@1$0#5@1$1@1$0#k0>1M>0@1$1@1$0#k0@1$8@1$1@1$0#8>3msF$a>2mo$h6>0@2$h4@2$eZ~0@2$e~0+jc>0@3$3$h2@2$2@1$1@1$0#k0^6Nhg3>0@3$3@1$1@1$0#k0@2$d^7N0?3sp0>0@3$3@1$1@1$0#k0@2$d^8Nod@2$6@1$0#k0~0>0@3$i8@1$b^9$hc^8>0@4$i7$5@1$b^a^8$hb>0@3$h9^8^7^9>0@3$3$a@3$hd?1L?1S^9@5$he?2fx^b@2$6@1$0#k0$ha^a@1$hf$5>0@3$3@1$8@1$4@1$1@1$0#8@4$c$5^b@2$6@1$0#k0~1@2$2@1$1@1$0#8?4path@2$9@1$4@1$1@1$0#8?4path>0@3$3@1$8@1$4@1$1@1$0#8@4$c$5^c@2$6@1$0#k0@2$i9~1~0N1@2$9@1$4@1$1@1$0#8@3$h1@1$1@1$0#8@2$6@1$0#8+a@1$h3@1$1@1$0#8@4$i1$5$i0@2$h5^c^b@2$i2@2$i4+2@1$i6?4path@2$i3@1$i5+2@1$h7?3mo0").
