    { rewrite EQ. apply buf_fact_block; [exact P0 | vm_compute; reflexivity | unfold BUF_LO, NPRE; lia | unfold BUF_HI; cbn; lia | exact SBn]. }
    clear EQ SBp SBn.
    buf_prefix HK P0 M' H17.
    assert (MSG : rdn RSEGS M' (Z_to_bv 64 (bv_unsigned sp0 + -592)) (19 + (length path + 1)) = Some (msg_read_error path)).
    { unfold msg_read_error. change (s2b _) with PRE17.
      apply rdn_app_Z; [exact H17 | | lia | lia]. apply rdn_app_Z; [| | lia | lia].
      + replace (bv_unsigned sp0 + -592 + Z.of_nat 19) with (bv_unsigned sp0 - 573) by lia. exact SBp'.
      + replace (bv_unsigned sp0 + -592 + Z.of_nat 19 + Z.of_nat (length path)) with (bv_unsigned sp0 - 573 + P) by lia. exact SBn'. }
    assert (LEN : length (msg_read_error path) = (19 + (length path + 1))%nat) by (unfold msg_read_error; rewrite !length_app; reflexivity).
    replace (W 2 (msg_read_error path)) with (map (WriteEv (Z_to_bv 64 2)) (msg_read_error path ++ [])) by (unfold W; rewrite app_nil_r; reflexivity).
    assert (FM' : frame_mod mem0 M' (tail_regions spm OT_FR)) by (eapply frame_mod_trans_same; [exact FM | exact F']).
